import{_ as t,o as e,c as p,a5 as r}from"./chunks/framework.BSWFn7Lx.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md/14-bat批处理-综合/1502-win系统虚拟内存一键修改.md","filePath":"md/14-bat批处理-综合/1502-win系统虚拟内存一键修改.md"}'),o={name:"md/14-bat批处理-综合/1502-win系统虚拟内存一键修改.md"};function n(i,a,s,l,h,c){return e(),p("div",null,[...a[0]||(a[0]=[r('<h2 id="_1501-批量提取指定文件夹下文件到各一级文件夹根目录" tabindex="-1">1501-批量提取指定文件夹下文件到各一级文件夹根目录 <a class="header-anchor" href="#_1501-批量提取指定文件夹下文件到各一级文件夹根目录" aria-label="Permalink to &quot;1501-批量提取指定文件夹下文件到各一级文件夹根目录&quot;">​</a></h2><blockquote><p>作者：极致办公 / 微信：reset201901</p></blockquote><p><img src="https://s2.loli.net/2024/11/02/tK9T7jxLcuv5rUk.png" alt="image"></p><h2 id="_1、程序用环境及相关说明" tabindex="-1">1、程序用环境及相关说明 <a class="header-anchor" href="#_1、程序用环境及相关说明" aria-label="Permalink to &quot;1、程序用环境及相关说明&quot;">​</a></h2><blockquote><p><strong>1、适用的系统环境说明</strong>： win7以上所有操作系统</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h2 id="_2、程序说明" tabindex="-1">2、程序说明 <a class="header-anchor" href="#_2、程序说明" aria-label="Permalink to &quot;2、程序说明&quot;">​</a></h2><p>用于调整 Windows 系统的虚拟内存（分页文件）大小。</p><p>一键设置win系统虚拟内存</p><p>设置分页文件（虚拟内存）大小对于操作系统的稳定性和性能有重要意义。分页文件是系统硬盘上的一部分空间，当物理内存（RAM）不足时，操作系统会将部分数据从内存临时转移到这个文件中，以继续运行程序。合理地设置分页文件大小有助于提高系统的效率和稳定性，</p><h2 id="_3、使用场景例子展示" tabindex="-1">3、使用场景例子展示 <a class="header-anchor" href="#_3、使用场景例子展示" aria-label="Permalink to &quot;3、使用场景例子展示&quot;">​</a></h2><p>设置C盘的虚拟内存大小；下图既是程序，可以放置在任意位置；</p><p><img src="https://s2.loli.net/2024/10/22/6IT12WfSn9UpgzP.png" alt="image-20241022111210187"></p><p>设置C盘虚拟内存大小为固定值2G，将程序放在D盘以管理员身份运行则设置D盘虚拟内存最小值为物理内存的1.5倍，最大值为物理内存的3倍。</p><p>下图即为程序，放在D盘根目录下或其他除C盘外的磁盘内，放在哪个盘就设置哪个盘虚拟内存最小值为物理内存的1.5倍，最大值为物理内存的3倍。</p><p><img src="https://s2.loli.net/2024/10/22/8MVc6z724LXaPju.png" alt="image-20241022111320051"></p><p>无论使用哪个程序，都需要确保磁盘有足够的空间，不然都会设置失败；</p><p>设置成功后，重启电脑，确保设置生效，虚拟内存涉及到win系统诸多配置，设置成功后重启最靠谱；</p><p>设置成功如下边截图说明中的显示即为全部成功。</p><h2 id="_4、程序截图说明" tabindex="-1">4、程序截图说明 <a class="header-anchor" href="#_4、程序截图说明" aria-label="Permalink to &quot;4、程序截图说明&quot;">​</a></h2><p>设置虚拟内存最小值为物理内存的1.5倍，最大值为物理内存的3倍</p><p><img src="https://s2.loli.net/2024/10/22/e9k8nhj6MJbVtDI.png" alt="image-20241022110451324"></p><p><img src="https://s2.loli.net/2024/10/22/IB8GuTVaUYqk7Ed.png" alt="image-20241022105123434"></p><p><strong>程序2：</strong></p><p>C盘设置2G，程序放在D盘根目录下运行，D盘设置最小值为物理内存的1.5倍，最大值为物理内存的3倍。</p><p><img src="https://s2.loli.net/2024/10/22/bTfotqRKycrsvmd.png" alt="image-20241022110524671"></p><p><strong>比如程序放在D盘根目录，如下图所示：</strong></p><p><img src="https://s2.loli.net/2024/10/22/sHxUqNbAMa76RI4.png" alt="image-20241022110039169"></p><p>程序放在D盘根目录下，设置C盘为2g，D盘最小值1.5倍物理内存，最大值3倍物理内存如图所示：</p><p><img src="https://s2.loli.net/2024/10/22/RoYvE13KgD7ViHk.png" alt="image-20241022105624628"></p><h2 id="_5、视频演示" tabindex="-1">5、视频演示 <a class="header-anchor" href="#_5、视频演示" aria-label="Permalink to &quot;5、视频演示&quot;">​</a></h2><iframe src="#" width="50%" height="80%"></iframe><h2 id="_6、友情提示" tabindex="-1">6、友情提示 <a class="header-anchor" href="#_6、友情提示" aria-label="Permalink to &quot;6、友情提示&quot;">​</a></h2><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><h2 id="_7、win-mac程序定制说明" tabindex="-1">7、win/mac程序定制说明 <a class="header-anchor" href="#_7、win-mac程序定制说明" aria-label="Permalink to &quot;7、win/mac程序定制说明&quot;">​</a></h2><blockquote><p>程序定制微信：reset201901</p><p>1、明确自身需求，直入主题，简要描述；</p><p>2、我第一步想要怎样，第二步想要怎样...；</p><p>3、最终想要的结果是什么样的，自己能够清晰的描述出来,</p><p>4、最好是用txt文档将以上需求写清楚，或者录制视频将需求讲述清楚；</p><p>5、提供需要做测试的文件给我们，如果文件不便展示，可以创建一个txt文件将文件名后缀.txt修改为你同类型的文件即可。</p></blockquote><h2 id="_8、本工具下载地址" tabindex="-1"><em>8、本工具下载地址</em> <a class="header-anchor" href="#_8、本工具下载地址" aria-label="Permalink to &quot;*8、本工具下载地址*&quot;">​</a></h2><p>下载地址：<a href="https://www.softbangong.top/?id=208" target="_blank" rel="noreferrer">https://www.softbangong.top/?id=208</a></p>',37)])])}const d=t(o,[["render",n]]);export{g as __pageData,d as default};
